/* Same-origin navigation unloads city WebGL before arena allocation. */
(()=>{'use strict';const button=document.createElement('button');button.type='button';button.id='city-boxing-open';button.className='primary';button.textContent='一分鐘拳台 · 榮譽對戰';document.querySelector('#player-area').prepend(button);button.onclick=async()=>{button.disabled=true;try{const r=await fetch('/api/session',{credentials:'same-origin'}),s=await r.json();if(!r.ok)throw Error('請先登入小城。');const e=await fetch('/api/boxing/enter',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json','x-city-csrf':s.csrf},body:'{}'}),d=await e.json();if(!e.ok)throw Error(d.error||'暫時無法進場');window.CozyWorld?.setActive(false);location.assign('/boxing/index.html?city=1');}catch(e){window.CozyWorld?.notify(e.message);button.disabled=false;}};window.addEventListener('pageshow',e=>{if(e.persisted)location.reload();});})();
